<style scoped>
/* Qwen's brand blue is DEEP - right on a light page, near-invisible on a
   dark one. Dark theme lifts the same hue instead of abandoning it. */
.vl__qwen {
  fill: #082dff;
}
[data-theme='dark'] .vl__qwen {
  fill: #5b7cff;
}
/* NB's brand red, same story as Qwen's blue: lifted on dark so the mark
   doesn't sink into the background at 16px. */
.vl__nb {
  fill: #c00a27;
}
[data-theme='dark'] .vl__nb {
